double GetBoxVolume(const BoundingBox3D& box) {
    double width = box.Max.x - box.Min.x;
    double height = box.Max.y - box.Min.y;
    double depth = box.Max.z - box.Min.z;
    return width * height * depth;
}

using namespace BasicTypesXYZ;
double GetBoxVolume(const BoundingBox3D& box) {
    double width = box.Max.x - box.Min.x;
    double height = box.Max.y - box.Min.y;
    double depth = box.Max.z - box.Min.z;
    return width * height * depth;
}

